			sources: {
				avif: "__VITE_ASSET__f63692be__ 1440w, __VITE_ASSET__7c12aaf8__ 960w",
				webp: "__VITE_ASSET__60e1d553__ 1440w, __VITE_ASSET__d0e3c982__ 960w",
				png: "__VITE_ASSET__ac99f329__ 1440w, __VITE_ASSET__33d52b23__ 960w"
